};

float rounded_box_sdf(vec2 p,vec2 b,float r){
    vec2 q=abs(p)-b+vec2(r);
    return length(max(q,0.0))+min(max(q.x,q.y),0.0)-r;
}

inline std::optional<double> signed_distance(double x,
                                             double y,
                                             double half_width,
                                             double half_height,
                                             double radius) noexcept {
    using detail::kMaxMagnitude;
    using detail::finite;

    if (!finite(x) || !finite(y) || !finite(half_width) ||
        !finite(half_height) || !finite(radius)) {
        return std::nullopt;
    }
    if (!(half_width > 0.0) || !(half_height > 0.0)) {
        return std::nullopt;
    }
    if (radius < 0.0) {
        return std::nullopt;
    }

    const double max_radius = (std::min)(half_width, half_height);
    if (radius > max_radius) {
        return std::nullopt;
    }

    const double ax = std::abs(x);
    const double ay = std::abs(y);
    if (ax > kMaxMagnitude || ay > kMaxMagnitude ||
        half_width > kMaxMagnitude || half_height > kMaxMagnitude) {
        return std::nullopt;
    }

    const double qx = ax - half_width + radius;
    const double qy = ay - half_height + radius;

    const double outside = std::hypot((std::max)(qx, 0.0), (std::max)(qy, 0.0));
    const double inside = (std::min)((std::max)(qx, qy), 0.0);
    return outside + inside - radius;
}

inline std::optional<double> opacity(double distance,
                                     double transition_width = 1.0) noexcept {
    using detail::finite;

    if (!finite(distance) || !finite(transition_width)) {
        return std::nullopt;
    }
    if (!(transition_width > 0.0)) {
        return std::nullopt;
    }

    const double t = (std::clamp)(distance / transition_width + 0.5, 0.0, 1.0);
    return 1.0 - t * t * (3.0 - 2.0 * t);
}

struct Vertex {
    float x,y,u,v,r,g,b,a;
    float local_x,local_y,half_width,half_height,radius;
};
static_assert(std::is_standard_layout_v<Vertex> && sizeof(Vertex)==52);
static_assert(offsetof(Vertex,u)==8 && offsetof(Vertex,r)==16);
static_assert(offsetof(Vertex,local_x)==32 && offsetof(Vertex,half_width)==40 && offsetof(Vertex,radius)==48);

inline std::optional<std::array<Vertex,6>> make_vertices(const Draw& draw) noexcept {
    const auto& rect=draw.image.rect;
    if(!std::isfinite(draw.radius) || draw.radius<0 || rect.width>1e6f || rect.height>1e6f ||
       draw.radius>(std::min)(rect.width,rect.height)*.5f) return std::nullopt;
    const auto base=study_image_quad::make_vertices(draw.image);
    if(!base)return std::nullopt;
    const float hw=rect.width*.5f,hh=rect.height*.5f;
    const float sx[6]={-1,-1,1,-1,1,1};
    const float sy[6]={-1,1,1,-1,1,-1};
    std::array<Vertex,6> result{};
    for(std::size_t i=0;i<result.size();++i){
        const auto& v=(*base)[i];
        result[i]={v.x,v.y,v.u,v.v,v.r,v.g,v.b,v.a,sx[i]*hw,sy[i]*hh,hw,hh,draw.radius};
    }
    return result;
}

